#[path = "solution.rs"]
mod solution;

use solution::{transform_meshes, GroupSummary, Mesh, MeshError, Point3, TransformOptions};

fn point(x: f64, y: f64, z: f64) -> Point3 {
    Point3 { x, y, z }
}

fn options(center_on_origin: bool, snap_to_ground: bool, analyze_groups: bool) -> TransformOptions {
    TransformOptions { center_on_origin, snap_to_ground, analyze_groups }
}

#[test]
fn transforms_global_bounds_and_preserves_input() {
    let meshes = vec![
        Mesh {
            group: "zeta".to_owned(),
            vertices: vec![point(0.0, 2.0, -2.0), point(4.0, 6.0, 2.0)],
        },
        Mesh {
            group: "alpha".to_owned(),
            vertices: vec![point(2.0, 4.0, 0.0)],
        },
    ];
    let original = meshes.clone();
    let result = transform_meshes(&meshes, options(true, true, false)).unwrap();

    assert_eq!(result.meshes[0].vertices, vec![point(-2.0, 0.0, -2.0), point(2.0, 4.0, 2.0)]);
    assert_eq!(result.meshes[1].vertices, vec![point(0.0, 2.0, 0.0)]);
    assert_eq!(result.meshes[0].group, "zeta");
    assert_eq!(result.meshes[1].group, "alpha");
    assert!(result.groups.is_empty());
    assert_eq!(meshes, original);
}

#[test]
fn snapping_without_centering_only_changes_vertical_position() {
    let meshes = vec![Mesh {
        group: "g".to_owned(),
        vertices: vec![point(3.0, -5.0, 8.0), point(-1.0, 1.0, 2.0)],
    }];
    let result = transform_meshes(&meshes, options(false, true, false)).unwrap();
    assert_eq!(result.meshes[0].vertices, vec![point(3.0, 0.0, 8.0), point(-1.0, 6.0, 2.0)]);
}

#[test]
fn group_analysis_is_exact_aggregated_and_lexicographically_sorted() {
    let meshes = vec![
        Mesh { group: "beta".to_owned(), vertices: vec![point(0.0, 0.0, 0.0)] },
        Mesh { group: "Alpha".to_owned(), vertices: vec![point(1.0, 1.0, 1.0), point(2.0, 2.0, 2.0)] },
        Mesh { group: "beta".to_owned(), vertices: vec![point(3.0, 3.0, 3.0), point(4.0, 4.0, 4.0)] },
        Mesh { group: "alpha".to_owned(), vertices: vec![point(5.0, 5.0, 5.0)] },
    ];
    let result = transform_meshes(&meshes, options(false, false, true)).unwrap();
    assert_eq!(result.meshes, meshes);
    assert_eq!(result.groups, vec![
        GroupSummary { group: "Alpha".to_owned(), mesh_count: 1, vertex_count: 2 },
        GroupSummary { group: "alpha".to_owned(), mesh_count: 1, vertex_count: 1 },
        GroupSummary { group: "beta".to_owned(), mesh_count: 2, vertex_count: 3 },
    ]);
}

#[test]
fn validates_meshes_and_vertices_in_index_order() {
    let empty_first = vec![
        Mesh { group: "empty".to_owned(), vertices: vec![] },
        Mesh { group: "bad".to_owned(), vertices: vec![point(f64::NAN, 0.0, 0.0)] },
    ];
    assert_eq!(transform_meshes(&empty_first, options(true, true, true)), Err(MeshError::EmptyMesh(0)));

    let non_finite = vec![
        Mesh { group: "ok".to_owned(), vertices: vec![point(0.0, 0.0, 0.0)] },
        Mesh { group: "bad".to_owned(), vertices: vec![point(1.0, 2.0, 3.0), point(4.0, f64::INFINITY, 6.0)] },
    ];
    assert_eq!(
        transform_meshes(&non_finite, options(false, false, false)),
        Err(MeshError::NonFiniteCoordinate { mesh: 1, vertex: 1 })
    );
}

#[test]
fn empty_input_always_produces_empty_output() {
    for opts in [options(false, false, false), options(true, true, true)] {
        let result = transform_meshes(&[], opts).unwrap();
        assert!(result.meshes.is_empty());
        assert!(result.groups.is_empty());
    }
}

